      <TabsContent value="storefront" class="mt-4"><MarketplaceBrandPreview v-if="storefrontLayout === 'marketplace'" :business="business" :logo="logo" :cover="heroVisual || coverPreview" /><div v-else class="mx-4 mb-4 overflow-hidden rounded-[var(--card-radius)] border bg-background" :style="storefrontBackground">
