        <div class="flex items-center justify-between border-b bg-background/95 px-3 py-2"><div class="flex items-center gap-2"><div class="grid h-7 w-7 place-items-center overflow-hidden rounded-[var(--button-radius)] bg-white"><img v-if="logo" :src="logo" alt="" class="h-full w-full object-contain" /><span v-else class="text-[10px] font-black">{{ initial }}</span></div><strong class="max-w-36 truncate text-xs">{{ business.display_name || 'Your business' }}</strong></div><div class="flex gap-2 text-[9px] font-bold"><span>Shop</span><span>Search</span><span>Bag</span></div></div>
        <div v-if="hero.enabled" class="relative flex overflow-hidden px-5 py-8 text-white" :class="heroLayout" :style="heroStyle"><img v-if="heroVisual" :src="heroVisual" alt="" class="absolute inset-0 h-full w-full object-cover" /><div v-else-if="['video', 'three'].includes(hero.type)" class="absolute inset-0 grid place-items-center text-[10px] font-bold text-white/55">Add a poster fallback to preview this media.</div><div class="absolute inset-0" :style="{ backgroundColor: hero.overlay_color, opacity: hero.overlay_opacity }" /><div class="relative z-10 max-w-[16rem]" :class="hero.alignment === 'center' ? 'text-center' : hero.alignment === 'right' ? 'text-right' : 'text-left'"><h3 class="text-xl font-bold leading-tight">{{ hero.heading || business.tagline || 'Make the first impression yours.' }}</h3><p class="mt-2 text-[10px] leading-4 text-white/80">{{ hero.description || business.description || 'Use clear copy and your own visual identity.' }}</p><div class="mt-3 flex gap-2" :class="hero.alignment === 'center' ? 'justify-center' : hero.alignment === 'right' ? 'justify-end' : ''"><span class="rounded-[var(--button-radius)] bg-[var(--brand-primary)] px-3 py-1.5 text-[9px] font-bold text-white">{{ hero.primary_cta_label || 'Primary action' }}</span><span v-if="hero.secondary_cta_label" class="rounded-[var(--button-radius)] border border-white/50 px-3 py-1.5 text-[9px] font-bold">{{ hero.secondary_cta_label }}</span></div></div></div>
        <div v-else class="px-5 py-9"><h3 class="text-xl font-extrabold">{{ business.tagline || 'Your storefront content continues here.' }}</h3><p class="mt-2 text-[10px] leading-4 text-muted-foreground">CMS hero content remains active until the global identity hero is enabled.</p></div>
        <div class="grid grid-cols-[1.1fr_.9fr] border-t bg-background" :class="storefrontMode === 'luxury' ? 'gap-0 p-0' : 'gap-3 p-4'"><div :class="storefrontMode === 'luxury' ? 'flex flex-col justify-end border-r p-4' : ''"><p class="text-[9px] font-bold text-muted-foreground">{{ storefrontMode === 'luxury' ? 'Editorial collection' : 'Component preview' }}</p><h3 class="mt-2 text-sm font-extrabold">{{ storefrontMode === 'luxury' ? 'Full-width product stories' : 'A consistent product surface' }}</h3><p class="mt-1 text-[9px] leading-4 text-muted-foreground">{{ storefrontMode === 'luxury' ? 'Contiguous imagery and restrained details lead the collection.' : 'Typography, links, controls, cards, borders, and shadows share one system.' }}</p><span class="mt-3 inline-flex w-fit rounded-[var(--button-radius)] bg-[var(--brand-primary)] px-3 py-1.5 text-[9px] font-bold text-white">Shop now</span></div><div class="border bg-card p-3" :class="storefrontMode === 'luxury' ? 'rounded-none border-y-0 border-r-0 shadow-none' : 'rounded-[var(--card-radius)] shadow-[var(--surface-shadow)]'"><div class="aspect-square bg-secondary" :class="storefrontMode === 'luxury' ? 'rounded-none' : 'rounded-[var(--input-radius)]'" /><p class="mt-2 text-[10px] font-bold">Featured product</p><p class="text-[9px] text-muted-foreground">Your catalog imagery</p></div></div>
