<script setup>
import { Badge } from '@/components/ui/badge'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { businessThemeStyle, readableForeground, storefrontBackgroundStyle } from '@/utils/businessTheme'
import SandboxedCustomization from './SandboxedCustomization.vue'
import MarketplaceBrandPreview from './MarketplaceBrandPreview.vue'
const props = defineProps({ business: { type: Object, required: true }, logoPreview: { type: String, default: '' }, coverPreview: { type: String, default: '' }, assets: { type: Object, default: () => ({}) } })
const activePreview = ref('storefront')
const branding = computed(() => props.business.branding || {})
const storefrontLayout = computed(() => branding.value.storefront?.layout === 'marketplace' ? 'marketplace' : 'brand')
const storefrontMode = computed(() => branding.value.storefront?.mode === 'luxury' ? 'luxury' : 'default')
const hero = computed(() => branding.value.storefront?.hero || {})
const banner = computed(() => branding.value.storefront?.banner || {})
const popup = computed(() => branding.value.storefront?.popup || {})
const footer = computed(() => branding.value.storefront?.footer || {})
const workspace = computed(() => branding.value.workspace || {})
const logo = computed(() => props.logoPreview || props.business.logo || '')
const initial = computed(() => (props.business.display_name || 'P').trim().charAt(0).toUpperCase())
const themeStyle = computed(() => businessThemeStyle(props.business))
const storefrontBackground = computed(() => storefrontBackgroundStyle({ ...props.business, branding_assets: props.assets }))
const sidebarForeground = computed(() => readableForeground(workspace.value.sidebar_color))
const heroMedia = computed(() => props.assets[hero.value.asset_id]?.url || '')
const heroPoster = computed(() => props.assets[hero.value.poster_asset_id]?.url || props.coverPreview || props.business.cover_image || '')
const heroVisual = computed(() => hero.value.type === 'image' ? heroMedia.value : heroPoster.value)
const heroLayout = computed(() => ({ center_left: 'items-center justify-start', center: 'items-center justify-center', center_right: 'items-center justify-end', bottom_left: 'items-end justify-start', bottom_center: 'items-end justify-center', bottom_right: 'items-end justify-end' }[hero.value.position] || 'items-center justify-start'))
const heroStyle = computed(() => ({ minHeight: hero.value.minimum_height === 'compact' ? '12rem' : hero.value.minimum_height === 'tall' ? '20rem' : hero.value.minimum_height === 'screen' ? '24rem' : '16rem', background: hero.value.type === 'gradient' ? `linear-gradient(${hero.value.gradient_angle || 135}deg, ${hero.value.gradient_from}, ${hero.value.gradient_to})` : hero.value.background_color }))
</script>
